// Combined test harness for rampart simulation.
function rampartSimulate(createStrategy, seed, maxTicks, opts) {
  opts = opts || {};
  const AIR_LEN_OVERRIDE = opts.airLen;

  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }

  // ----- static definitions -----
  const SLOT_TILES = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  const GROUND_ROUTE = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
  const AIR_ROUTE = [[0,6],[21,6],[21,11],[23,11]];
  const TURRET_DEFS = {
    bolt:   {cost:50,  damage:26,  period:8,  range:300, splash:0,  slow:0,  pierce:false, ground:true,  air:true,  idx:0},
    cannon: {cost:90,  damage:60,  period:24, range:260, splash:90, slow:0,  pierce:false, ground:true,  air:false, idx:1},
    frost:  {cost:70,  damage:10,  period:12, range:240, splash:0,  slow:30, pierce:false, ground:true,  air:true,  idx:2},
    lance:  {cost:120, damage:180, period:36, range:360, splash:0,  slow:0,  pierce:true,  ground:true,  air:false, idx:3},
    flak:   {cost:80,  damage:40,  period:10, range:320, splash:70, slow:0,  pierce:false, ground:false, air:true,  idx:4}
  };
  const TURRET_NAMES = ['bolt','cannon','frost','lance','flak'];
  const TYPE_DEFS = {
    grunt:     {baseHp:60, speed:10, armorFn:function(w){return Math.floor(w/4);}, bounty:4, leak:1, air:false, first:1, weight:10},
    runner:    {baseHp:40, speed:20, armorFn:function(w){return 0;}, bounty:4, leak:1, air:false, first:2, weight:4},
    wisp:      {baseHp:50, speed:12, armorFn:function(w){return 0;}, bounty:6, leak:2, air:true,  first:3, weight:3},
    brute:     {baseHp:150,speed:6,  armorFn:function(w){return 6+w;}, bounty:9, leak:3, air:false, first:4, weight:3},
    splitter:  {baseHp:90, speed:8,  armorFn:function(w){return 0;}, bounty:6, leak:2, air:false, first:6, weight:2},
    mender:    {baseHp:70, speed:8,  armorFn:function(w){return 0;}, bounty:7, leak:2, air:false, first:8, weight:1}
  };
  const TYPE_ORDER = ['grunt','runner','wisp','brute','splitter','mender'];

  function makeRoute(points) {
    const segs = [];
    let len = 0;
    for (let i = 1; i < points.length; i++) {
      const ax = points[i-1][0]*100+50, ay = points[i-1][1]*100+50;
      const bx = points[i][0]*100+50, by = points[i][1]*100+50;
      const dx = bx-ax, dy = by-ay;
      const l = Math.abs(dx)+Math.abs(dy);
      segs.push({ax,ay,bx,by,dx,dy,len:l,start:len});
      len += l;
    }
    return {segs, len};
  }
  const groundRoute = makeRoute(GROUND_ROUTE);
  const airRoute = makeRoute(AIR_ROUTE);
  if (AIR_LEN_OVERRIDE != null) airRoute.len = AIR_LEN_OVERRIDE;

  function routePoint(route, progress) {
    let p = progress;
    for (let i = 0; i < route.segs.length; i++) {
      const s = route.segs[i];
      if (p <= s.len - 1 || i === route.segs.length - 1) {
        if (s.len === 0) return [s.ax, s.ay];
        // axis aligned
        let f = p / s.len;
        if (f < 0) f = 0;
        if (f > 1) f = 1;
        return [s.ax + s.dx * f, s.ay + s.dy * f];
      }
      p -= s.len;
    }
    const last = route.segs[route.segs.length-1];
    return [last.bx, last.by];
  }

  // ----- generator & wave data -----
  const rng = mulberry32(seed >>> 0);
  function generateWave(w) {
    const avail = [];
    let sum = 0;
    for (let i = 0; i < TYPE_ORDER.length; i++) {
      const name = TYPE_ORDER[i], def = TYPE_DEFS[name];
      if (def.first <= w) { avail.push([name, def.weight]); sum += def.weight; }
    }
    const count = 4 + Math.floor(3*w/5);
    const out = [];
    for (let i = 0; i < count; i++) {
      let r = rng() % sum;
      let picked = avail[avail.length-1][0];
      for (let j = 0; j < avail.length; j++) {
        if (r < avail[j][1]) { picked = avail[j][0]; break; }
        r -= avail[j][1];
      }
      out.push(picked);
    }
    return out;
  }

  const hpMult = [0, 1000];
  function ensureHpMult(w) {
    while (hpMult.length <= w) {
      const p = hpMult.length - 1;
      hpMult.push(Math.floor(hpMult[p] * 108 / 100));
    }
    return hpMult[w];
  }

  let currentWaveComp = generateWave(1);
  let nextWave = null;

  // ----- state -----
  const slots = [];
