    slots.push({slot:i, x:SLOT_TILES[i][0]*100+50, y:SLOT_TILES[i][1]*100+50, turret:null});
  }
  const cooldowns = new Array(16).fill(0);
  const turretDamage = {}; // per slot cached? use func
  let gold = 250, baseHp = 10, wave = 0, tick = 0;
  let nextId = 1;
  let enemies = [];
  let pending = [];
  const log = [];
  const strategy = createStrategy();

  function enemyX(e) { return routePoint(e.route, e.progress)[0]; }
  function enemyY(e) { return routePoint(e.route, e.progress)[1]; }
  function makeView(e) {
    const pt = routePoint(e.route, e.progress);
    return {id:e.id, type:e.type, hp:e.hp, maxHp:e.maxHp, x:pt[0], y:pt[1],
      air:e.air?1:0, armor:e.armor, speed:e.speed, slowed:e.slow, remaining:e.len-e.progress};
  }
  function makeState() {
    return {
      tick: tick, wave: wave, gold: gold, baseHp: baseHp,
      slots: slots.map(function(s){ return {slot:s.slot, x:s.x, y:s.y,
        turret: s.turret ? {type:s.turret.type, tier:s.turret.tier, spent:s.turret.spent} : null}; }),
      enemies: enemies.map(makeView),
      nextWave: nextWave ? nextWave.slice() : []
    };
  }

  function turretDamageOf(t) {
    const def = TURRET_DEFS[t.type];
    let d = def.damage;
    if (t.tier >= 2) d = Math.floor(d*16/10);
    if (t.tier >= 3) d = Math.floor(d*16/10);
    return d;
  }
  function turretRangeOf(t) {
    return TURRET_DEFS[t.type].range + (t.tier-1)*30;
  }

  function spawnEnemy(type, w, progress, route, hpOverride) {
    let cfg;
    let air = false;
    let maxHp;
    let armor;
    let bounty;
    let leak;
    let speed;
    if (type === 'splitling') {
      cfg = {speed:12, bounty:1, leak:1, air:false};
      maxHp = hpOverride;
      armor = 0;
      speed = cfg.speed;
      bounty = cfg.bounty;
      leak = cfg.leak;
      air = false;
      route = groundRoute;
    } else {
      cfg = TYPE_DEFS[type];
      air = cfg.air;
      maxHp = Math.floor(cfg.baseHp * ensureHpMult(w) / 1000);
      armor = cfg.armorFn(w);
      speed = cfg.speed;
      bounty = cfg.bounty;
      leak = cfg.leak;
      route = air ? airRoute : groundRoute;
    }
    if (maxHp < 1) maxHp = 1;
    const e = {
      id: nextId++, type: type, wave: w, route: route, len: route.len,
      progress: progress, maxHp: maxHp, hp: maxHp, age: 0, slow: 0,
      armor: armor, speed: speed, slowSpeed: Math.floor(speed*60/100),
      bounty: bounty, leak: leak, air: air
    };
    enemies.push(e);
    return e;
  }

  function spawnPending() {
    if (!pending.length) return;
    const due = [];
    const rest = [];
    for (let i = 0; i < pending.length; i++) {
      if (pending[i].tick === tick) due.push(pending[i]); else rest.push(pending[i]);
    }
    pending = rest;
    due.sort(function(a,b){ return (a.wave-b.wave) || (a.index-b.index); });
    for (let i = 0; i < due.length; i++) {
      const p = due[i];
      spawnEnemy(p.type, p.wave, 0, null, 0);
    }
  }

