// Evaluation harness; expects engine.js loaded first.
function simScore(factory, seed, maxTicks) {
  try {
    return rampartSimulate(factory, seed, maxTicks == null ? 20000 : maxTicks);
  } catch (e) {
    return {score: -1, fallTick: -1, err: String(e), log: []};
  }
}
function evalSeeds(factory, seeds, maxTicks, verbose) {
  var arr = [];
  for (var i = 0; i < seeds.length; i++) {
    var r = simScore(factory, seeds[i], maxTicks);
    arr.push(r.score);
    if (verbose) print('seed', seeds[i], r.score, r.fallTick, r.err || '');
  }
  var sum = 0, min = 1e9, max = -1;
  for (var j = 0; j < arr.length; j++) { sum += arr[j]; if (arr[j]<min)min=arr[j]; if(arr[j]>max)max=arr[j]; }
  return {mean: sum/arr.length, min: min, max: max, scores: arr};
}
function rngSeeds(n, start) { var a=[]; for (var i=0;i<n;i++) a.push((start||1)+i); return a; }
var SEEDS = rngSeeds(20, 1);
function show(name, factory, seeds) {
  var t0 = Date.now ? Date.now() : 0;
  var r = evalSeeds(factory, seeds || SEEDS, 20000);
  print(name, 'mean', r.mean.toFixed(3), 'min', r.min, 'max', r.max, 'scores', JSON.stringify(r.scores));
  return r;
}

// ---------- candidate strategy factories ----------
// 1. Greedy bolts (reference-ish baseline)
function cAllBolt() {
  return { plan: function(s) {
    var a=[], g=s.gold;
    for (var i=0;i<s.slots.length;i++){var sl=s.slots[i]; if(!sl.turret && g>=50){a.push({op:'build',slot:sl.slot,type:'bolt'});g-=50;}}
    return a;
  }};
}
show('allbolt', cAllBolt);

// 2. Fixed purchase sequence, executed greedily.
function makeSeqStrategy(seq, opts) {
  opts = opts||{};
  return function() {
    var next = 0; // cached build actions state
    return { plan: function(s) {
      var a=[], g=s.gold;
      // slots/type map
      var bySlot={}; for (var i=0;i<s.slots.length;i++) bySlot[s.slots[i].slot]=s.slots[i];
      // ensure desired sequence structures built as affordable
      while (next < seq.length) {
        var it = seq[next];
        var sl = bySlot[it.slot];
        if (!sl) { next++; continue; }
        if (it.type) {
          if (sl.turret) { next++; continue; }
          var cost = it.cost;
          if (g < cost) break;
          a.push({op:'build',slot:it.slot,type:it.type}); g-=cost; next++;
        } else {
          next++;
        }
      }
      // upgrades: requested fixed list after builds, or if we cannot build next due gold and max slots?
      if (opts.upgrades) {
        for (var u=0;u<opts.upgrades.length;u++) {
          var up=opts.upgrades[u]; var sl2=bySlot[up.slot];
          if (!sl2||!sl2.turret) continue;
          var want=up.tier||opts.upTier||3;
          while (sl2.turret.tier<want) {
            var c=up.costFor ? up.costFor(sl2.turret) : upgradeCost(sl2.turret.type,sl2.turret.tier);
            if(g<c)break;
            a.push({op:'upgrade',slot:up.slot});g-=c;sl2.turret.tier++;sl2.turret.spent+=c;
          }
        }
      }
      return a;
    }};
  };
}
function upgradeCost(type,tier){
  var base={bolt:50,cannon:90,frost:70,lance:120,flak:80}[type];
  return base*(tier===1?1:2);
}

