function effSpeed(e){return e.slowed>0?Math.floor(e.speed*60/100):e.speed;}
var TARGETS={};
TARGETS.minTime=function(t,c){
  var best=c[0], bd=1e18;
  for(var i=0;i<c.length;i++){var e=c[i];var tt=e.remaining/effSpeed(e);if(tt<bd){bd=tt;best=e;}}
  return best.id;
};
TARGETS.minTimeLowHp=function(t,c){
  var best=c[0], bs=1e18;
  for(var i=0;i<c.length;i++){var e=c[i];var tt=e.remaining/effSpeed(e);var sc=tt + e.hp*0.02;if(sc<bs){bs=sc;best=e;}}
  return best.id;
};
TARGETS.cluster=function(t,c){
  if(t.type!=='flak'&&t.type!=='cannon')return TARGETS.minTime(t,c);
  var rad=t.type==='flak'?70:90,br2=rad*rad;
  var best=c[0],bs=-1;
  for(var i=0;i<c.length;i++){
    var a=c[i],cnt=0;
    for(var j=0;j<c.length;j++){var b=c[j];var dx=a.x-b.x,dy=a.y-b.y;if(dx*dx+dy*dy<=br2)cnt++;}
    var tt=a.remaining/effSpeed(a);
    var sc=cnt*1000 - tt;
    if(sc>bs){bs=sc;best=a;}
  }
  return best.id;
};
TARGETS.clusterDmg=function(t,c){
  if(t.type!=='flak'&&t.type!=='cannon')return TARGETS.minTime(t,c);
  var rad=t.type==='flak'?70:90,br2=rad*rad;
  var dmgBase={flak:40,cannon:60}[t.type];
  var dmg=t.tier>=2?Math.floor(dmgBase*16/10):dmgBase;
  if(t.tier>=3)dmg=Math.floor(dmg*16/10);
  var best=c[0],bs=-1;
  for(var i=0;i<c.length;i++){
    var a=c[i],score=0;
    for(var j=0;j<c.length;j++){var b=c[j];var dx=a.x-b.x,dy=a.y-b.y;if(dx*dx+dy*dy<=br2){var act=Math.max(1,dmg-b.armor);var threat=1/(1+b.remaining/effSpeed(b)/100);score+=Math.min(act,b.hp)*threat;}}
    if(score>bs){bs=score;best=a;}
  }
  return best.id;
};
TARGETS.lanceBrute=function(t,c){
  if(t.type==='lance'){
    var b=null,bd=1e18;
    for(var i=0;i<c.length;i++){var e=c[i];if(e.type==='brute'){var tt=e.remaining/effSpeed(e);if(tt<bd){bd=tt;b=e;}}}
    if(b)return b.id;
  }
  return TARGETS.minTime(t,c);
};
TARGETS.smart=function(t,c){
  if(t.type==='flak'||t.type==='cannon')return TARGETS.clusterDmg(t,c);
  if(t.type==='lance'){
    // kill the most advanced brute, else most advanced high-HP armored enemy, else leak threat
    var best=c[0],bs=-1e18;
    for(var i=0;i<c.length;i++){
      var e=c[i];var tt=e.remaining/effSpeed(e);
      var pri=(e.type==='brute'?3000:0)+e.armor*20+e.hp*0.2-tt;
      if(pri>bs){bs=pri;best=e;}
    }
    return best.id;
  }
  if(t.type==='frost'){
    var bf=null,bfs=1e18;
    for(var k=0;k<c.length;k++){var e2=c[k];var ts=e2.remaining/effSpeed(e2)+(e2.slowed>0?500:0);if(ts<bfs){bfs=ts;bf=e2;}}
    return bf.id;
  }
  return TARGETS.minTime(t,c);
};
