function eff(e){return e.slowed>0?Math.floor(e.speed*60/100):e.speed;}
function tt(e){return e.remaining/eff(e);}
function minTime(c){var b=c[0],bd=1e18;for(var i=0;i<c.length;i++){var v=tt(c[i]);if(v<bd){bd=v;b=c[i];}}return b;}
function maxTime(c){var b=c[0],bd=-1;for(var i=0;i<c.length;i++){var v=tt(c[i]);if(v>bd){bd=v;b=c[i];}}return b;}
function lowestHp(c){var b=c[0],bv=1e18;for(var i=0;i<c.length;i++){if(c[i].hp<bv){bv=c[i].hp;b=c[i];}}return b;}
function dmgOf(t){var b={bolt:26,cannon:60,frost:10,lance:180,flak:40}[t.type];if(t.tier>=2)b=Math.floor(b*16/10);if(t.tier>=3)b=Math.floor(b*16/10);return b;}
function splashRad(t){return t.type==='flak'?70:t.type==='cannon'?90:0;}
function inRad(a,b,r2){var dx=a.x-b.x,dy=a.y-b.y;return dx*dx+dy*dy<=r2;}
var splashScorers={
  count:function(t,c,a,r2){var n=0;for(var j=0;j<c.length;j++)if(inRad(a,c[j],r2))n++;return n*1000-tt(a);},
  countRem:function(t,c,a,r2){var n=0;for(var j=0;j<c.length;j++)if(inRad(a,c[j],r2))n++;return n*1000-a.remaining;},
  threatSum:function(t,c,a,r2){var s=0;for(var j=0;j<c.length;j++){var b=c[j];if(inRad(a,b,r2))s+=1/(1+tt(b));}return s*1000-tt(a);},
  hpSum:function(t,c,a,r2){var s=0;for(var j=0;j<c.length;j++){var b=c[j];if(inRad(a,b,r2))s+=Math.min(b.hp,dmgOf(t));}return s;},
  kills:function(t,c,a,r2){var d=dmgOf(t),n=0;for(var j=0;j<c.length;j++){var b=c[j];if(inRad(a,b,r2)){var act=Math.max(1,d-b.armor);if(act>=b.hp)n++;}}return n*1000-tt(a);},
  killDmg:function(t,c,a,r2){var d=dmgOf(t),s=0;for(var j=0;j<c.length;j++){var b=c[j];if(inRad(a,b,r2)){var act=Math.max(1,d-b.armor);s+=Math.min(act,b.hp);}}return s;},
  weightedCount:function(t,c,a,r2){var n=0;for(var j=0;j<c.length;j++){var b=c[j];if(inRad(a,b,r2))n+=1+Math.max(0,10-tt(b))*0.1;}return n*1000-tt(a);},
  advance:function(t,c,a,r2){var n=0;for(var j=0;j<c.length;j++)if(inRad(a,c[j],r2))n++;return n===0?-1e9:n*1e6-a.remaining;}
};
var splashNames=['count','countRem','threatSum','hpSum','kills','killDmg','weightedCount','advance'];
