function chooseNon(t,c,mode){
  if(mode==='base')return null;
  if(mode==='minTime')return minTime(c).id;
  if(mode==='rem'){var b=c[0];for(var i=1;i<c.length;i++)if(c[i].remaining<b.remaining)b=c[i];return b.id;}
  if(mode==='minTimeHp'){var b2=c[0],bs=1e18;for(var j=0;j<c.length;j++){var s=tt(c[j])+c[j].hp*.02;if(s<bs){bs=s;b2=c[j];}}return b2.id;}
  if(mode==='lowHpTime'){var b3=c[0],bs3=1e18;for(var k=0;k<c.length;k++){var tt3=tt(c[k]);var s3=tt3*(1+c[k].hp/c[k].maxHp);if(s3<bs3){bs3=s3;b3=c[k];}}return b3.id;}
  if(mode==='highHpTime'){var b4=c[0],bs4=1e18;for(var q=0;q<c.length;q++){var s4=tt(c[q])-c[q].hp*.01;if(s4<bs4){bs4=s4;b4=c[q];}}return b4.id;}
  if(mode==='brute'){var br=null,bd=1e18;if(t.type==='lance'){for(var p=0;p<c.length;p++){var e=c[p];if(e.type==='brute'&&tt(e)<bd){bd=tt(e);br=e;}}}if(br)return br.id;return minTime(c).id;}
  if(mode==='lowHp'){var lh=lowestHp(c); if(lh.remaining <= 500) return lh.id; return minTime(c).id;}
  return null;
}
function mkTarget(splashMode,nonMode){
  return function(t,c){
    var rad=splashRad(t);
    if(rad>0){
      var r2=rad*rad,b=c[0],bs=-1e30;
      for(var i=0;i<c.length;i++){var v=splashScorers[splashMode](t,c,c[i],r2);if(v>bs){bs=v;b=c[i];}}
      return b.id;
    }
    return chooseNon(t,c,nonMode);
  };
}
