// Shared targeting heuristics for tuning. Cluster splash, min time-to-leak otherwise.
function makeClusterTarget() {
  return function(t, c) {
    var rad = t.type === 'flak' ? 70 : t.type === 'cannon' ? 90 : 0;
    var i, j, e;
    if (rad > 0) {
      var r2 = rad * rad, best = c[0], bestCount = -1, bestRem = 1e18;
      for (i = 0; i < c.length; i++) {
        e = c[i];
        var n = 0;
        for (j = 0; j < c.length; j++) {
          var o = c[j], dx = e.x - o.x, dy = e.y - o.y;
          if (dx*dx + dy*dy <= r2) n++;
        }
        if (n > bestCount || (n === bestCount && e.remaining < bestRem)) {
          bestCount = n; bestRem = e.remaining; best = e;
        }
      }
      return best.id;
    }
    var bt = 1e18, bestE = c[0];
    for (i = 0; i < c.length; i++) {
      e = c[i];
      var sp = e.slowed > 0 ? Math.floor(e.speed * 60 / 100) : e.speed;
      var tt = e.remaining / sp;
      if (tt < bt) { bt = tt; bestE = e; }
    }
    return bestE.id;
  };
}

function upgradeCost3(type,tier){var base={bolt:50,cannon:90,frost:70,lance:120,flak:80}[type];return base*(tier===1?1:2);}
function makeLayout3(layout) {
  return function() {
    return { target: makeClusterTarget(), plan: function(s) {
      var actions=[],g=s.gold,built={};
      for(var i=0;i<s.slots.length;i++){var sl=s.slots[i];built[sl.slot]=sl.turret?{type:sl.turret.type,tier:sl.turret.tier}:null;}
      for(var slot=0;slot<16;slot++){
        var type=layout[slot];if(!type||built[slot])continue;
        var cost={bolt:50,cannon:90,frost:70,lance:120,flak:80}[type];
        if(g<cost)continue;
        actions.push({op:'build',slot:slot,type:type});g-=cost;built[slot]={type:type,tier:1};
      }
      for(var pass=0;pass<3;pass++)for(var slot2=0;slot2<16;slot2++){
        var t=built[slot2];if(!t||t.tier>=3)continue;
        var c=upgradeCost3(t.type,t.tier);if(g<c)continue;
        actions.push({op:'upgrade',slot:slot2});g-=c;t.tier++;
      }
      return actions;
    }};
  };
}
function evalRich(layout,seeds){var f=makeLayout3(layout),arr=[];for(var i=0;i<seeds.length;i++)arr.push(rampartSimulate(f,seeds[i],20000).score);var s=0;for(var j=0;j<arr.length;j++)s+=arr[j];return {m:s/arr.length,a:arr};}
function shuffle(a){for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));var t=a[i];a[i]=a[j];a[j]=t;}return a;}
function randomCounts(){
  // random counts via ranges, reject invalid
  for(var tries=0;tries<100;tries++){
    var c={lance:1+Math.floor(Math.random()*6),cannon:Math.floor(Math.random()*5),flak:1+Math.floor(Math.random()*5),bolt:Math.floor(Math.random()*7),frost:Math.random()<0.15?1:0};
    var n=c.lance+c.cannon+c.flak+c.bolt+c.frost;
    if(n===16 && c.flak+c.bolt>=2)return c;
  }
  return {lance:4,cannon:3,flak:3,bolt:6,frost:0};
}
function layoutFromCounts(counts){
  var arr=[];
  for(var type in counts)for(var i=0;i<counts[type];i++)arr.push(type);
  shuffle(arr);var L={};for(var j=0;j<16;j++)L[j]=arr[j];return L;
}
