function perm16(){var a=[];for(var i=0;i<16;i++)a.push(i);for(var i=15;i>0;i--){var j=Math.floor(Math.random()*(i+1));var t=a[i];a[i]=a[j];a[j]=t;}return a;}
function scoreOrder(bo,uo){
