function climb(rounds){
  for(var rd=0;rd<rounds;rd++){
    var improved=false;
    for(var k=0;k<16;k++)for(var j=k+1;j<16;j++){
      var bo2=best.bo.slice();var t=bo2[k];bo2[k]=bo2[j];bo2[j]=t;
      var r3=scoreOrder(bo2,best.uo);
      if(r3.m>best.m+1e-9){best={m:r3.m,mn:r3.mn,bo:bo2,uo:best.uo};print('BSWAP',r3.m.toFixed(3),JSON.stringify(bo2));improved=true;}
    }
    for(var k2=0;k2<16;k2++)for(var j2=k2+1;j2<16;j2++){
