  var LAYOUT = {0:'flak',1:'flak',2:'cannon',3:'cannon',4:'cannon',5:'cannon',6:'cannon',7:'cannon',8:'cannon',9:'cannon',10:'cannon',11:'cannon',12:'flak',13:'bolt',14:'flak',15:'flak'};
