  var UPGRADE_ORDER = [4,3,7,6,13,0,1,14,8,5,11,9,10,2,12,15];
  var COST = {bolt:50,cannon:90,frost:70,lance:120,flak:80};
  function effectiveSpeed(e) { return e.slowed > 0 ? Math.floor(e.speed * 60 / 100) : e.speed; }
  return {
    plan: function(s) {
      var actions = [], g = s.gold, bySlot = {}, i;
      for (i = 0; i < s.slots.length; i++) {
        var sl = s.slots[i];
        bySlot[sl.slot] = sl.turret ? {type:sl.turret.type, tier:sl.turret.tier} : null;
      }
      for (var bi = 0; bi < BUILD_ORDER.length && actions.length < 32; bi++) {
        var slot = BUILD_ORDER[bi], type = LAYOUT[slot];
        if (!type || bySlot[slot]) continue;
        var cost = COST[type];
        if (g < cost) continue;
        actions.push({op:'build', slot:slot, type:type});
        g -= cost; bySlot[slot] = {type:type, tier:1};
      }
      for (var pass = 0; pass < 3 && actions.length < 32; pass++) {
        var did = false;
        for (var ui = 0; ui < UPGRADE_ORDER.length && actions.length < 32; ui++) {
          var us = UPGRADE_ORDER[ui], t = bySlot[us];
          if (!t || t.tier >= 3) continue;
          var uc = COST[t.type] * (t.tier === 1 ? 1 : 2);
          if (g < uc) continue;
          actions.push({op:'upgrade', slot:us});
          g -= uc; t.tier += 1; did = true;
        }
        if (!did) break;
      }
      return actions;
    },
    target: function(t, candidates) {
      var radius = t.type === 'flak' ? 70 : t.type === 'cannon' ? 90 : 0;
      var i, j, e;
      if (radius > 0) {
        var r2 = radius * radius, best = candidates[0], bestScore = -1e30;
        for (i = 0; i < candidates.length; i++) {
          e = candidates[i];
          var count = 0;
          for (j = 0; j < candidates.length; j++) {
            var o = candidates[j], dx = e.x - o.x, dy = e.y - o.y;
            if (dx*dx + dy*dy <= r2) count++;
