/* ================================================================
   RENDER + FIXED-CLOCK PLAYBACK
   ================================================================ */
var lastCheckedFrame = -1;
var mouseIdle = 0;
function frameAtTime(time) {
  var rawTick = time * TICKS_PER_SECOND;
  var k = Math.floor(rawTick + 1e-7);
  if (k < 0) k = 0;
  var last = lastFrameIndex;
  var kk = Math.min(k, last);
  var alpha = 0;
  if (kk < last) {
    alpha = rawTick - kk;
    if (alpha < 0) alpha = 0;
    if (alpha > 1) alpha = 1;
  }
  var a = frames[kk] || frames[last] || frames[0];
  var b = (kk < last ? frames[kk + 1] : a) || a;
  return { a: a, b: b, alpha: alpha, kk: kk };
}

function valueNoise(t, channel) {
  var i = Math.floor(t), f = t - i;
  f = f * f * (3 - 2 * f);
  var h0 = hash01((i * 977 + channel * 131 + 42) | 0);
  var h1 = hash01(((i + 1) * 977 + channel * 131 + 42) | 0);
  return h0 + (h1 - h0) * f;
}
function currentTrauma(time) {
  var tr = 0;
  for (var i = 0; i < leaks.length; i++) {
    var t = leaks[i].tick / TICKS_PER_SECOND;
    if (time >= t) tr += 0.3 * Math.max(0, 1 - (time - t));
  }
  if (fallTime < 1e8 && time >= fallTime) tr += Math.max(0, 1 - (time - fallTime));
  return Math.min(1, tr);
}
var shakeVec = new THREE.Vector3();
var lookVec = new THREE.Vector3();
var hudTime = 0;
var lastRenderedTime = -1;

function renderAt(time) {
  if (time < 0) time = 0; else if (time > DURATION) time = DURATION;
  var fallNow = fallTime < 1e8 && time >= fallTime;
  var animationTime = fallNow ? fallTime : time;
  var sampled = frameAtTime(time);
  syncTurrets(sampled.a);
  var tr = currentTrauma(time);
  var amp = tr * tr * 0.25;
  shakeVec.set(
    (valueNoise(time * 5.1 + 0.3, 11) * 2 - 1) * amp,
    (valueNoise(time * 5.5 + 3.7, 23) * 2 - 1) * amp * 0.45,
    (valueNoise(time * 4.7 + 7.1, 37) * 2 - 1) * amp
