window.contentView = webView
window.orderFrontRegardless()
let nav = NavDelegate()
webView.navigationDelegate = nav
webView.loadFileURL(indexURL, allowingReadAccessTo: workspace)
print("LOADING", indexURL.path)

func eval(_ js: String, label: String, completion: @escaping (Any?) -> Void) {
    webView.evaluateJavaScript(js) { value, error in
        if let error = error { print("EVALERR[\(label)]:", error.localizedDescription) }
        print("EVAL[\(label)]:", value.map { String(describing: $0) } ?? "nil")
        completion(value)
    }
}

func snapshot(_ name: String, completion: @escaping () -> Void) {
    let cfg = WKSnapshotConfiguration()
    cfg.rect = NSRect(x: 0, y: 0, width: 1280, height: 650)
    webView.takeSnapshot(with: cfg) { image, error in
        if let error = error { print("SNAPERR:", error.localizedDescription); completion(); return }
        guard let image = image, let tiff = image.tiffRepresentation, let rep = NSBitmapImageRep(data: tiff) else {
            print("SNAPERR: no image"); completion(); return
        }
        if let png = rep.representation(using: .png, properties: [:]) {
            let url = outDir.appendingPathComponent(name)
            do { try png.write(to: url); print("SNAP:", url.path) } catch { print("SNAPWRITEERR:", error.localizedDescription) }
        }
        completion()
    }
}

